import { TableName } from './table-names.js';

/**
 * The schema expressed as data, not hand-written DDL. A {@link SchemaDef} per version lists its
 * tables; each column carries a logical {@link ColumnType} plus optional flags. Per-flavour
 * extras (indexes, constraints, shard keys) attach per table so each engine renders only what it
 * supports. Concrete DDL is produced by {@link renderSchema}; migrations are generated by diffing
 * consecutive versions (see the migration layer). No hand-written `CREATE TABLE` strings elsewhere.
 */

/** Logical column types, mapped to physical types per flavour by {@link TYPE_SQL}. */
export enum ColumnType {
  TEXT = 'TEXT',
  INTEGER = 'INTEGER',
  BIGINT = 'BIGINT',
  SMALLINT = 'SMALLINT',
  REAL = 'REAL',
}

/** The DDL dialects we render. Multiple engines can share one flavour (PGLite uses PG). */
export enum SchemaFlavour {
  PG = 'PG',
  SQLITE = 'SQLITE',
}

export interface ColumnDef {
  name: string;
  type: ColumnType;
  notNull?: boolean;
  /** A rendered default: a number, or a string literal already including its quotes (e.g. `"'FIXED'"`). */
  default?: string | number;
}

export interface TableDef {
  name: TableName;
  columns: ColumnDef[];
}

export interface SchemaDef {
  version: number;
  /** Stable identifier recorded with the applied migration for this version. */
  checksum: string;
  tables: TableDef[];
}

/**
 * Logical → physical type per flavour. Today PG and SQLite agree (SQLite takes these via type
 * affinity; BIGINT avoids Postgres' 32-bit INTEGER overflow for epoch-ms), but the seam is here so
 * a future flavour can diverge (e.g. Oracle `VARCHAR2`/`NUMBER`) without touching callers.
 */
const TYPE_SQL: Record<SchemaFlavour, Record<ColumnType, string>> = {
  [SchemaFlavour.PG]: {
    [ColumnType.TEXT]: 'TEXT',
    [ColumnType.INTEGER]: 'INTEGER',
    [ColumnType.BIGINT]: 'BIGINT',
    [ColumnType.SMALLINT]: 'SMALLINT',
    [ColumnType.REAL]: 'REAL',
  },
  [SchemaFlavour.SQLITE]: {
    [ColumnType.TEXT]: 'TEXT',
    [ColumnType.INTEGER]: 'INTEGER',
    [ColumnType.BIGINT]: 'BIGINT',
    [ColumnType.SMALLINT]: 'SMALLINT',
    [ColumnType.REAL]: 'REAL',
  },
};

/** Render one column's DDL fragment, e.g. `priority INTEGER NOT NULL DEFAULT 0`. */
export function renderColumnDdl(flavour: SchemaFlavour, col: ColumnDef): string {
  let sql = `${col.name} ${TYPE_SQL[flavour][col.type]}`;
  if (col.notNull) sql += ' NOT NULL';
  if (col.default !== undefined) sql += ` DEFAULT ${col.default}`;
  return sql;
}

/** Render a single `CREATE TABLE IF NOT EXISTS` for one table on one flavour. */
export function renderCreateTable(
  flavour: SchemaFlavour,
  table: TableDef,
  physicalName: (t: TableName) => string,
): string {
  const cols = table.columns.map((c) => `  ${renderColumnDdl(flavour, c)}`).join(',\n');
  return `CREATE TABLE IF NOT EXISTS ${physicalName(table.name)} (\n${cols}\n)`;
}

/** Render every table of a schema version for one flavour, in declaration order. */
export function renderSchema(
  flavour: SchemaFlavour,
  schema: SchemaDef,
  physicalName: (t: TableName) => string,
): string[] {
  return schema.tables.map((t) => renderCreateTable(flavour, t, physicalName));
}
